CREATE DATABASE IF NOT EXISTS cybershield CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE cybershield;

CREATE TABLE organizations (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(160) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, org_id BIGINT UNSIGNED NOT NULL, email VARCHAR(254) NOT NULL, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(140) NOT NULL, role ENUM('admin','analyst','reporter','viewer') NOT NULL DEFAULT 'reporter', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_user_org_email (org_id,email), CONSTRAINT fk_user_org FOREIGN KEY (org_id) REFERENCES organizations(id));
CREATE TABLE incident_sequences (org_id BIGINT UNSIGNED NOT NULL, year SMALLINT UNSIGNED NOT NULL, last_value INT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY (org_id,year), FOREIGN KEY (org_id) REFERENCES organizations(id));
CREATE TABLE incidents (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, org_id BIGINT UNSIGNED NOT NULL, incident_key VARCHAR(24) NOT NULL, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, category VARCHAR(80) NOT NULL, severity ENUM('Low','Medium','High','Critical') NOT NULL DEFAULT 'Medium', status ENUM('New','Triaged','Investigating','In Progress','Resolved','Closed') NOT NULL DEFAULT 'New', affected_asset VARCHAR(255), reported_by BIGINT UNSIGNED NOT NULL, assigned_to BIGINT UNSIGNED, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_incident_org_key (org_id,incident_key), KEY ix_incident_org_status_severity (org_id,status,severity), KEY ix_incident_assignee_status (assigned_to,status), KEY ix_incident_created (org_id,created_at), FOREIGN KEY (org_id) REFERENCES organizations(id), FOREIGN KEY (reported_by) REFERENCES users(id), FOREIGN KEY (assigned_to) REFERENCES users(id));
CREATE TABLE incident_audit_log (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, incident_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, action VARCHAR(40) NOT NULL, details JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY ix_audit_incident_time (incident_id,created_at), FOREIGN KEY (incident_id) REFERENCES incidents(id), FOREIGN KEY (actor_id) REFERENCES users(id));
CREATE TABLE agent_runs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, incident_id BIGINT UNSIGNED NOT NULL, agent_name ENUM('osint-collection','vulnerability-assessment','threat-intelligence','risk-analysis-reporting') NOT NULL, status ENUM('queued','running','completed','failed') NOT NULL DEFAULT 'queued', input_json JSON, result_json JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMP NULL, KEY ix_agent_incident_status (incident_id,status), FOREIGN KEY (incident_id) REFERENCES incidents(id));

